<div class="scrim" id="cart-scrim"></div><aside class="cart-drawer" id="cart-drawer" role="dialog" aria-modal="true" aria-label="Shopping cart" aria-hidden="true"><div class="cart-header"><h2 data-en="Your shopping cart" data-bn="আপনার শপিং কার্ট">{{ t('Your shopping cart','আপনার শপিং কার্ট') }}</h2><button type="button" class="icon-btn" id="cart-close" aria-label="Close cart"><svg><use href="#ic-close"/></svg></button></div><div class="cart-items" id="cart-items"></div><div class="cart-footer"><div class="cart-subtotal"><span data-en="Subtotal" data-bn="সাবটোটাল">{{ t('Subtotal','সাবটোটাল') }}</span><strong id="cart-total">৳0</strong></div><button class="checkout-btn" type="button" id="checkout-demo" data-en="Proceed to checkout" data-bn="চেকআউট করুন">{{ t('Proceed to checkout','চেকআউট করুন') }}</button><div class="cart-note" data-en="Demo storefront — online checkout will be connected later." data-bn="ডেমো স্টোরফ্রন্ট—অনলাইন চেকআউট পরে যুক্ত হবে।">{{ t('Demo storefront — online checkout will be connected later.','ডেমো স্টোরফ্রন্ট—অনলাইন চেকআউট পরে যুক্ত হবে।') }}</div></div></aside>
<div class="toast" id="store-toast" role="status" aria-live="polite"></div>
<nav class="mobile-nav" aria-label="Mobile navigation"><button class="active" type="button" id="mobile-home"><svg><use href="#ic-home"/></svg><span data-en="Home" data-bn="হোম">{{ t('Home','হোম') }}</span></button><button type="button" id="mobile-categories"><svg><use href="#ic-grid"/></svg><span data-en="Categories" data-bn="ক্যাটাগরি">{{ t('Categories','ক্যাটাগরি') }}</span></button><button type="button" id="mobile-search"><svg><use href="#ic-search"/></svg><span data-en="Search" data-bn="খুঁজুন">{{ t('Search','খুঁজুন') }}</span></button><button type="button" id="mobile-favorites"><svg><use href="#ic-heart"/></svg><span data-en="Saved" data-bn="পছন্দ">{{ t('Saved','পছন্দ') }}</span></button><button type="button" id="mobile-cart"><svg><use href="#ic-bag"/></svg><span data-en="Cart" data-bn="কার্ট">{{ t('Cart','কার্ট') }}</span></button></nav>
<script>
(()=>{
const storeKey=@json((string)$storeCode),langKey='nexabiz-language',themeKey='nexabiz-theme',cartKey='public-shop-cart:'+storeKey,favKey='public-shop-favorites:'+storeKey;
const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
const tr=(en,bn)=>(document.documentElement.lang==='bn'?bn:en);
const safeRead=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch(e){return fallback}};
const safeSave=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value))}catch(e){}};
const products={};$$('.product-card').forEach(card=>{products[card.dataset.productId]={id:card.dataset.productId,en:card.dataset.productNameEn,bn:card.dataset.productNameBn,price:Number(card.dataset.productPrice),image:card.dataset.productImage}});
let cart=safeRead(cartKey,{}),favorites=safeRead(favKey,[]),toastTimer=null;
if(!cart||typeof cart!=='object'||Array.isArray(cart))cart={};if(!Array.isArray(favorites))favorites=[];
const formatMoney=value=>'৳'+Number(value).toLocaleString('en-BD',{maximumFractionDigits:0});
const toast=(en,bn)=>{const el=$('#store-toast');el.textContent=tr(en,bn);el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)};
const updateLang=()=>{const bn=document.documentElement.lang==='bn';$$('[data-en][data-bn]').forEach(el=>el.textContent=bn?el.dataset.bn:el.dataset.en);$$('[data-placeholder-en][data-placeholder-bn]').forEach(el=>el.placeholder=bn?el.dataset.placeholderBn:el.dataset.placeholderEn);$('#language-toggle').textContent=bn?'EN':'বাংলা';renderCart();};
const updateTheme=()=>{$('#theme-symbol').setAttribute('href',document.documentElement.dataset.theme==='dark'?'#ic-sun':'#ic-moon')};
const getQty=id=>Math.max(0,Number(cart[id]||0));
const updateCounts=()=>{const total=Object.keys(cart).reduce((n,id)=>n+getQty(id),0);$('#cart-count').textContent=total;$('#cart-count').hidden=!total;$('#wishlist-count').textContent=favorites.length;$('#wishlist-count').hidden=!favorites.length;$$('.wish-btn').forEach(btn=>{const id=btn.closest('.product-card').dataset.productId;btn.classList.toggle('selected',favorites.includes(id));btn.setAttribute('aria-pressed',favorites.includes(id)?'true':'false')})};
const renderCart=()=>{const container=$('#cart-items');const entries=Object.entries(cart).filter(([id,qty])=>products[id]&&qty>0);container.innerHTML='';if(!entries.length){const empty=document.createElement('div');empty.className='cart-empty';empty.innerHTML='<svg><use href="#ic-bag"/></svg>';const label=document.createElement('div');label.textContent=tr('Your cart is empty. Start exploring!','আপনার কার্ট খালি। পণ্য দেখা শুরু করুন!');empty.appendChild(label);container.appendChild(empty)}let sum=0;entries.forEach(([id,qty])=>{const p=products[id];sum+=qty*p.price;const row=document.createElement('div');row.className='cart-row';const img=document.createElement('img');img.src=p.image;img.alt=p.en;const detail=document.createElement('div');detail.className='cart-row-info';const title=document.createElement('strong');title.textContent=tr(p.en,p.bn);const price=document.createElement('small');price.textContent=formatMoney(p.price);const quantity=document.createElement('div');quantity.className='qty-control';const minus=document.createElement('button');minus.type='button';minus.textContent='−';minus.setAttribute('aria-label','Decrease quantity');minus.onclick=()=>setQuantity(id,qty-1);const count=document.createElement('span');count.textContent=qty;const plus=document.createElement('button');plus.type='button';plus.textContent='+';plus.setAttribute('aria-label','Increase quantity');plus.onclick=()=>setQuantity(id,qty+1);quantity.append(minus,count,plus);detail.append(title,price,quantity);row.append(img,detail);container.appendChild(row)});$('#cart-total').textContent=formatMoney(sum);updateCounts()};
const setQuantity=(id,qty)=>{if(!products[id])return;if(qty<=0)delete cart[id];else cart[id]=Math.min(99,qty);safeSave(cartKey,cart);renderCart()};
const addCart=id=>{setQuantity(id,getQty(id)+1);toast('Added to your cart','কার্টে যোগ করা হয়েছে')};
const toggleFavorite=id=>{favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];safeSave(favKey,favorites);updateCounts();toast(favorites.includes(id)?'Saved to wishlist':'Removed from wishlist',favorites.includes(id)?'পছন্দের তালিকায় রাখা হয়েছে':'পছন্দের তালিকা থেকে সরানো হয়েছে')};
const setScrim=()=>$('#cart-scrim').classList.toggle('open',$('#cart-drawer').classList.contains('open')||$('#side-nav').classList.contains('open'));
const openCart=()=>{$('#side-nav').classList.remove('open');$('#cart-drawer').classList.add('open');$('#cart-drawer').setAttribute('aria-hidden','false');setScrim()};
const closePanels=()=>{$('#side-nav').classList.remove('open');$('#cart-drawer').classList.remove('open');$('#cart-drawer').setAttribute('aria-hidden','true');setScrim()};
const openSide=()=>{$('#cart-drawer').classList.remove('open');$('#cart-drawer').setAttribute('aria-hidden','true');$('#side-nav').classList.add('open');setScrim()};
const filterProducts=()=>{const query=$('#store-search').value.trim().toLocaleLowerCase();let visible=0;$$('.product-section').forEach(section=>{let sectionVisible=0;const category=(section.dataset.sectionEn+' '+section.dataset.sectionBn).toLocaleLowerCase();section.querySelectorAll('.product-card').forEach(card=>{const match=!query||category.includes(query)||(card.dataset.productNameEn+' '+card.dataset.productNameBn).toLocaleLowerCase().includes(query);card.classList.toggle('hidden',!match);card.style.display=query&&match?'block':'';if(match){sectionVisible++;visible++}});section.classList.toggle('hidden',sectionVisible===0)});$('#search-empty').style.display=visible?'none':'block';$$('.editorial').forEach(el=>el.classList.toggle('hidden',Boolean(query)));};
$('#language-toggle').addEventListener('click',()=>{document.documentElement.lang=document.documentElement.lang==='bn'?'en':'bn';try{localStorage.setItem(langKey,document.documentElement.lang)}catch(e){}updateLang()});
$('#theme-toggle').addEventListener('click',()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem(themeKey,document.documentElement.dataset.theme)}catch(e){}updateTheme()});
$$('.add-btn').forEach(btn=>btn.onclick=()=>addCart(btn.closest('.product-card').dataset.productId));$$('.wish-btn').forEach(btn=>btn.onclick=()=>toggleFavorite(btn.closest('.product-card').dataset.productId));
$('#cart-open').onclick=openCart;$('#mobile-cart').onclick=openCart;$('#cart-close').onclick=closePanels;$('#cart-scrim').onclick=closePanels;$('#open-mobile-menu').onclick=openSide;$('#mobile-categories').onclick=()=>{closePanels();$('#categories').scrollIntoView({behavior:'smooth'})};$('#mobile-home').onclick=()=>{closePanels();window.scrollTo({top:0,behavior:'smooth'})};
$('#account-open').onclick=()=>toast('Customer account will be available soon','কাস্টমার অ্যাকাউন্ট শিগগিরই আসবে');$('#checkout-demo').onclick=()=>toast('Checkout integration is coming next','চেকআউট ইন্টিগ্রেশন পরে যুক্ত হবে');
$('#wishlist-open').onclick=$('#mobile-favorites').onclick=()=>{const saved=favorites.length;if(!saved)return toast('No saved products yet','এখনো কোনো পণ্য সেভ করা হয়নি');closePanels();$$('.product-card').forEach(card=>card.classList.toggle('hidden',!favorites.includes(card.dataset.productId)));$$('.product-section').forEach(section=>section.classList.toggle('hidden',!section.querySelector('.product-card:not(.hidden)')));$('#search-empty').style.display='none';toast('Showing your saved products','আপনার পছন্দের পণ্য দেখানো হচ্ছে');document.querySelector('.product-section:not(.hidden)')?.scrollIntoView({behavior:'smooth'})};
$('#store-search-form').onsubmit=e=>{e.preventDefault();filterProducts();document.querySelector('.product-section:not(.hidden)')?.scrollIntoView({behavior:'smooth'})};$('#store-search').oninput=filterProducts;$('#mobile-search-field').oninput=()=>{$('#store-search').value=$('#mobile-search-field').value;filterProducts()};
$('#mobile-search').onclick=()=>{$('#mobile-search-tray').classList.toggle('open');if($('#mobile-search-tray').classList.contains('open'))$('#mobile-search-field').focus()};$('#mobile-search-tray').onsubmit=e=>{e.preventDefault();$('#store-search').value=$('#mobile-search-field').value;filterProducts();$('#mobile-search-tray').classList.remove('open');document.querySelector('.product-section:not(.hidden)')?.scrollIntoView({behavior:'smooth'})};
$$('a[href^="#"]').forEach(link=>link.addEventListener('click',()=>{if($('#store-search').value||$$('.product-card.hidden').length){$('#store-search').value='';$('#mobile-search-field').value='';filterProducts()}}));$$('.side-link').forEach(link=>link.addEventListener('click',()=>{closePanels();$$('.side-link').forEach(x=>x.classList.remove('active'));link.classList.add('active')}));
$$('.section-more').forEach(link=>link.onclick=e=>{e.preventDefault();const section=link.closest('.product-section');const cards=section.querySelectorAll('.product-card');if(!link.dataset.expanded){cards.forEach(card=>card.style.display='block');link.dataset.expanded='1';link.querySelector('span').textContent=tr('Show less','কম দেখুন')}else{cards.forEach(card=>card.style.display='');delete link.dataset.expanded;link.querySelector('span').textContent=tr('View all','সব দেখুন')}});
window.addEventListener('keydown',e=>{if(e.key==='Escape')closePanels()});updateLang();updateTheme();updateCounts();renderCart();
})();
</script>
</body>
</html>
